Ca serait bien d'ajouter une condition de ciblage d'inactivité sur le site
Du genre : inactivité de scroll, de clic, de clavier ...
Par exemple (avec un consol.log) :
let inactiveTimer;
function resetTimer() {
  clearTimeout(inactiveTimer);
  inactiveTimer = setTimeout(() => {
    console.log("Vous êtes inactif depuis 3 secondes.");
    // Supprimer les écouteurs d'événements après l'inactivité de 3 secondes
    document.removeEventListener("mousemove", handleActivity);
    document.removeEventListener("keydown", handleActivity);
    document.removeEventListener("touchstart", handleActivity);
    document.removeEventListener("scroll", handleActivity);
  }, 3000); // 3 secondes
}
function handleActivity() {
  resetTimer();
}
document.addEventListener("mousemove", handleActivity);
document.addEventListener("keydown", handleActivity);
document.addEventListener("touchstart", handleActivity);
document.addEventListener("scroll", handleActivity);
resetTimer();
